    results['equivariance_identities'].append({'q':q,'n':m.n,'coarse':math.prod(math.comb(len(g)+q-1,q-1) for g in gg),
                 'HQB_minus_R_max':err,'HB_minus_I_max':hb,'strong_exact':exact})

